$root=dirname(__DIR__);$v=json_decode(file_get_contents($root.'/outputs/catalog-publication-verification-20261112.json'),true,512,JSON_THROW_ON_ERROR);$preview=json_decode(file_get_contents($root.'/outputs/catalog-publication-preview-20261112.json'),true,512,JSON_THROW_ON_ERROR);$preservation=json_decode(file_get_contents($root.'/outputs/catalog-publication-preservation-20261112.json'),true,512,JSON_THROW_ON_ERROR);$schedule=json_decode(file_get_contents($root.'/outputs/catalog-feed-schedule-20261112.json'),true,512,JSON_THROW_ON_ERROR);$e=static fn($x)=>htmlspecialchars((string)$x,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
$html='<!doctype html><html lang="ru"><head><meta charset="utf-8"><title>Подключение характеристик к карточкам и YML</title><style>body{font:16px/1.55 system-ui,sans-serif;max-width:1100px;margin:40px auto;padding:0 24px;color:#17334a}h1,h2{line-height:1.2}table{border-collapse:collapse;width:100%;font-size:14px}td,th{border:1px solid #cbd9e3;padding:9px;text-align:left;vertical-align:top}th{background:#eaf2f8}a{color:#086ab4}.note{background:#f1f5f8;padding:18px;border-left:4px solid #2182b4}code{overflow-wrap:anywhere}</style></head><body><h1>Характеристики подключены к карточкам и YML</h1><p>12 ноября 2026. Публикация завершена, 8 файлов.</p><div class="note">Подтверждённые поля с источником из единой базы используются в карточке товара и при формировании фида спецшин. Для остальных полей сохраняются прежние значения. Все 880 черновых профилей и 304 отложенных замечания сохранены; автоматических подтверждений нет.</div><h2>Как работать</h2><ol><li>Открыть <a href="https://its-center.ru/admin/catalog-properties">единый каталог</a> и нужный товар.</li><li>Для будущей проверки сохранять сведения как «Исторические данные» или «Предложение» — они не заменяют публичные характеристики.</li><li>После сверки выбрать «Подтверждено», указать документ/фото/источник и сохранить. Подходящие подтверждённые поля сразу используются карточкой.</li><li>В блоке «Подключение к сайту и YML» отображаются поля, фактически выбранные из сохранённой версии. Несохранённый предпросмотр ничего не публикует.</li><li>Фид получает изменения при формировании <a href="https://its-center.ru/admin/cron">задания обновления</a> №32. Рабочая ссылка фида сохранена.</li></ol><h2>Границы подключения</h2><ul><li>Неизвестные, неподтверждённые и противоречивые новые значения не подменяют старые поля. Неверный профиль/сочетание свойств отклоняет подмену.</li><li>Взаимозаменяемость действует только для конкретного товара, неизменившегося основного размера и подтверждённой связи. Условные связи не превращаются в безусловные; частично проверенный старый список размеров не обрезается.</li><li>Отдельные режимы нагрузки сохраняются отдельными строками. PR, индексы, давление и единицы не выводятся догадкой.</li><li>Название, H1, адрес, идентификатор, цена, остатки и фильтры каталога этой связкой не редактируются.</li><li>Применены только изменения этого этапа поверх текущих серверных версий карточки. Параллельные локальные правки оформления/корзины не публиковались.</li></ul><h2>Состояние данных</h2><p>Подтверждённых новых скалярных полей сейчас 0. Подтверждена одна связь размеров у IT000007251: основной 12-16.5, альтернативный 33x12-20. Она подключена как связь только этой карточки. Остальные данные остаются черновыми по решению владельца; подключение не означает, что они все проверены.</p><h2>Выгрузка</h2><table><tr><th>Показатель</th><th>Результат</th></tr><tr><td>Предложений до / после</td><td>140 / '.$v['feed']['offers'].'</td></tr><tr><td>Снято из фида из-за отсутствия свободного остатка</td><td>6, с учётом резервов</td></tr><tr><td>Существующих изображений выбрано взамен прежних ссылок</td><td>2</td></tr><tr><td>Цена, название, URL и характеристики общих предложений</td><td>Совпадают; различаются только две ссылки picture</td></tr><tr><td>XML / публичная ссылка</td><td>Корректен / HTTP '.$v['feed']['http'].'</td></tr></table><p>Снятые SKU: '.$e(implode(', ',$preview['removed_skus'])).'. Их текущий свободный остаток проверен отдельно и равен нулю; сами товары с сайта не удалялись.</p><p><a href="https://its-center.ru/cron/ymlfid_specshiny.xml">Рабочий YML спецшин</a>. Характеристики передаются через param, как предусмотрено <a href="https://yandex.ru/support/merchants/ru/export/vendor-model">документацией Яндекс Товаров</a>.</p><h2>Проверки и резервная копия</h2><ul><li>Пройдены проверки нормализации/подмены, чтения БД, транзакций, отсутствия записи в исходные данные, XML, цены, остатков, фото, дубликатов SKU, редактора и очереди.</li><li>До переключения выполнено сравнение текущего и нового XML. Рабочий файл заменён атомарно после проверки XML; прежний файл сохранён.</li><li>880 профилей, исходные таблицы и прежние строки журнала сверены с резервной копией. Правила отложенных исправлений остались прежними.</li><li>Три публичные карточки проверены HTTP-запросами: пилот, EK-3936A и товар с отложенными данными. Все отвечают 200; короткое название EK-3936A сохранено.</li><li>Полная резервная копия базы — 368832256 байт; прежние файлы и XML сохранены в закрытой папке сервера. Проверка авторизованного интерфейса в живом браузере в этот этап не входила; формы и чтение/сохранение проверены тестами.</li></ul><h2>Автоматический запуск</h2><p>Генератор задания №32 подключён и успешно выполнен при публикации. Расписание внешнего планировщика Beget по SSH не подтверждено: команда crontab в окружении недоступна (код '.$schedule['crontab_exit'].'). Это не доказывает отсутствие задания в панели хостинга. Регулярный автоматический вызов следует проверить в панели Beget отдельно; до этой проверки гарантирован результат выполненного обновления.</p><p>Технические результаты: <code>outputs/catalog-publication-verification-20261112.json</code>, <code>outputs/catalog-publication-preservation-20261112.json</code>, <code>outputs/catalog-publication-preview-20261112.json</code>.</p></body></html>';
file_put_contents($root.'/docs/catalog-publication-20261112.html',$html);echo json_encode(['verified_files'=>$v['verified_files'],'offers'=>$v['feed']['offers'],'profiles'=>$v['profiles'],'deferred_reviews'=>$v['review_statuses']['deferred'],'old_rows_preserved'=>!in_array(false,$preservation['existing_shadow_rows_unchanged'],true),'product_unchanged_except_sync_timestamp'=>$preservation['product_unchanged_except_sync_timestamp']],JSON_UNESCAPED_UNICODE),PHP_EOL;
